// Nodo: Validacion y Enriquecimiento del Mensaje de Alerta
const body = $input.first().json.body;

// 1. Validacion basica: si no trae los campos minimos, cortamos el flujo
if (!body || !body.order_id) {
  throw new Error('Payload invalido: falta order_id');
}

// 2. Privacidad (Ley 25.326): usamos pseudonimo si esta disponible, nunca nombre real
const identidad = body.patient_pseudonym || body.patient || 'Paciente Anonimizado';

// 3. Diferenciamos visualmente segun criticidad
const esCritico = body.is_critical === true;

let emoji = '⚠️';
let nivel = 'URGENTE';
if (esCritico) {
  emoji = '🆘';
  nivel = 'CRITICO';
}

// 4. Construimos el mensaje estructurado
const lineas = [
  `${emoji} ALERTA ${nivel} — RadioGroup`,
  `👤 Paciente: ${identidad}`,
  `📋 Diagnóstico: ${body.diagnosis || 'Sin especificar'}`,
  `🏥 Ubicación: ${body.location || 'Sin especificar'}`,
  `🔬 Servicio: ${body.setting || 'Sin especificar'}`,
  `🆔 Orden #${body.order_id}`,
  `⏱️ Recibido: ${new Date().toLocaleString('es-AR')}`,
];

const mensaje = lineas.join('\n');

return [{
  json: {
    mensaje,
    nivel,
    order_id: body.order_id,
    identidad,
  }
}];

// Nodo: Log de Resultado
